record.field:
partner = tools.find("res.partner", customer_name) or record.partner_id
if not partner:
    raise UserError("La factura necesita un cliente.")
invoice_lines = []
for line in tools.lines(lines, extra="price"):
    product = tools.find("product.product", line["name"])
    vals = {"name": line["name"], "quantity": line["quantity"]}
    if product:
        vals["product_id"] = product.id
    if line["price"]:
        try:
            vals["price_unit"] = float(line["price"])
        except ValueError:
            raise UserError("Precio ilegible en la línea '%s'." % line["name"])
    invoice_lines.append((0, 0, vals))
move = env["account.move"].create({
    "move_type": "out_invoice",
    "partner_id": partner.id,
    "invoice_date": datetime.date.today(),
    "invoice_origin": record._tool_origin(),
    "narration": note or False,
    "invoice_line_ids": invoice_lines,
})
ai["result"] = {"model": "account.move", "id": move.id}

{
    "type": "object",
    "properties": {
        "customer_name": {"type": "string", "description": "Vacío = cliente de la conversación"},
        "lines": {"type": "array", "items": {"type": "string"}, "description": "Una línea por concepto: 'producto o concepto | cantidad | precio unitario'"},
        "note": {"type": "string"}
    },
    "required": ["lines"]
}
